#!/usr/bin/env bash
# Generated by scripts/build-deploy.sh — do not edit directly.
# setup-gh-cli.sh — Installs/updates GitHub CLI (gh)
# Safe to re-run — detects existing install and upgrades as needed.
#
# macOS: Uses Homebrew (brew install gh).
# Linux: Uses apt + GitHub CLI keyring (added on first install only).
#        Falls back with warning on non-apt systems.
#
# Auth (gh auth login) is interactive — handled by aitools-install Step 2, not here.
#
# See reference/tool-registry.md for install source details.

set -euo pipefail

# --- Shared library ---
# aitools-lib.sh -- shared helpers for all aitools bash scripts
# Sourced, not executed directly. No shebang, no set -euo pipefail (caller sets it).
#
# Provides: platform detection, display_path, read_config_key, logging_init,
# log/log_ok/log_error/log_warn, write_summary, show_summary.
#
# Usage:
#   source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/aitools-lib.sh"
#   logging_init "script-name"
#
# Entry points (aitools, aitools-install) override log functions after sourcing
# for specialized logging (file-only, JSONL, etc.).

# ---------------------------------------------------------------------------
# Platform detection
# ---------------------------------------------------------------------------
IS_MACOS=false
IS_WINDOWS=false
case "$(uname -s)" in
    Darwin*)              IS_MACOS=true ;;
    MINGW*|MSYS*|CYGWIN*) IS_WINDOWS=true ;;
esac

# ---------------------------------------------------------------------------
# Log directory (platform-aware)
# ---------------------------------------------------------------------------
AITOOLS_LOG_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/aitools"
$IS_MACOS && AITOOLS_LOG_DIR="$HOME/Library/Logs/aitools"

# ---------------------------------------------------------------------------
# Module-level counters (safe for sourcing without logging_init under set -u)
# ---------------------------------------------------------------------------
ERRORS=0
WARNINGS=0

# ---------------------------------------------------------------------------
# Display-friendly path (native Windows on MSYS, no-op elsewhere)
# ---------------------------------------------------------------------------
display_path() {
    if command -v cygpath &>/dev/null; then
        cygpath -w "$1"
    else
        printf '%s' "$1"
    fi
}

# ---------------------------------------------------------------------------
# Config reader (pure bash, handles UTF-8 BOM)
# ---------------------------------------------------------------------------
# Read a top-level string value from a JSON config file.
# Handles UTF-8 BOM (PowerShell 5.x writes one) and JSON-escaped backslashes.
read_config_key() {
    local file="$1" key="$2"
    [ -f "$file" ] || return 1
    local val
    val=$(tr -d '\357\273\277' < "$file" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | cut -d'"' -f4)
    [ -n "$val" ] || return 1
    # Unescape JSON backslashes: \\ -> \
    printf '%b' "$val"
}

# ---------------------------------------------------------------------------
# Logging init
# ---------------------------------------------------------------------------
# Sets SCRIPT_NAME, LOG_DIR, LOG_FILE; resets ERRORS, WARNINGS; creates log dir.
# Usage: logging_init "setup-foo"
logging_init() {
    SCRIPT_NAME="${1:?logging_init requires a script name}"
    LOG_DIR="$AITOOLS_LOG_DIR"
    LOG_FILE="$LOG_DIR/deploy.log"
    mkdir -p "$LOG_DIR"
    ERRORS=0
    WARNINGS=0
}

# ---------------------------------------------------------------------------
# Standard logging (Pattern A: console + log file, with [level] tag)
# ---------------------------------------------------------------------------
log() {
    local level="${2:-info}"
    local ts; ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    local line="[$ts] [$SCRIPT_NAME] [$level] $1"
    printf '%s\n' "$line" >> "$LOG_FILE"
    case "$level" in
        error) printf '\033[31m%s\033[0m\n' "$line" ;;
        warn)  printf '\033[33m%s\033[0m\n' "$line" ;;
        *)     printf '%s\n' "$line" ;;
    esac
}
log_ok()    { log "$1" "ok"; }
log_error() { log "$1" "error"; ERRORS=$((ERRORS + 1)); }
log_warn()  { log "$1" "warn"; WARNINGS=$((WARNINGS + 1)); }

# ---------------------------------------------------------------------------
# Summary writer (3-arg: category, tool, detail)
# ---------------------------------------------------------------------------
write_summary() {
    [ -n "${AITOOLS_SUMMARY_FILE:-}" ] && printf '%s|%s|%s\n' "$1" "$2" "$3" >> "$AITOOLS_SUMMARY_FILE"
}

# ---------------------------------------------------------------------------
# Summary panel renderer
# ---------------------------------------------------------------------------
# Reads AITOOLS_SUMMARY_FILE, displays colored panel, cleans up.
# Silent no-op if file unset, missing, or empty.
show_summary() {
    local sfile="${AITOOLS_SUMMARY_FILE:-}"
    [ -n "$sfile" ] || return 0
    [ -f "$sfile" ] || return 0
    [ -s "$sfile" ] || { rm -f "$sfile"; return 0; }
    echo ""
    echo "────────────────────────────────────────────────────────"
    while IFS='|' read -r cat tool detail; do
        [ "$cat" = "OK"   ] && printf '\033[32m  [ok]  %-16s %s\033[0m\n' "$tool" "$detail"
    done < "$sfile"
    while IFS='|' read -r cat tool detail; do
        [ "$cat" = "WARN" ] && printf '\033[33m  [!]   %-16s %s\033[0m\n' "$tool" "$detail"
    done < "$sfile"
    while IFS='|' read -r cat tool detail; do
        [ "$cat" = "ERROR" ] && printf '\033[31m  [ERR] %-16s %s\033[0m\n' "$tool" "$detail"
    done < "$sfile"
    local first_action=true
    while IFS='|' read -r cat tool detail; do
        if [ "$cat" = "ACTION" ]; then
            if [ "$first_action" = true ]; then
                echo ""
                printf '\033[1;35m  ACTION REQUIRED -- run before tools are ready:\033[0m\n'
                first_action=false
            fi
            printf '\033[1;35m  >>  %s\033[0m\n' "$detail"
        fi
    done < "$sfile"
    echo "────────────────────────────────────────────────────────"
    rm -f "$sfile"
}
logging_init "setup-gh-cli"

# --- OS guard ---
case "$(uname -s)" in
    MINGW*|MSYS*|CYGWIN*)
        log_error "This script is for macOS/Linux. On Windows, use ${SCRIPT_NAME}.ps1 instead."
        exit 1 ;;
esac

OS_NAME="$(uname -s)"

# --- Install/update ---
case "$OS_NAME" in
    Darwin)
        # macOS: Homebrew is the preferred method
        if ! command -v brew &>/dev/null; then
            log_error "Homebrew not found. Install gh manually:"
            log_error "  1. Install Homebrew: https://brew.sh"
            log_error "  2. brew install gh"
            exit 1
        fi

        if command -v gh &>/dev/null; then
            log "gh CLI already installed ($(gh --version | head -1))"
            log "Checking for updates via Homebrew..."
            UPGRADE_OUTPUT=$(brew upgrade gh 2>&1) || true
            if printf '%s\n' "$UPGRADE_OUTPUT" | grep -qi 'already installed\|up.to.date\|No available upgrade'; then
                log_ok "gh CLI already up to date"
            else
                printf '%s\n' "$UPGRADE_OUTPUT" | while IFS= read -r line; do log "$line"; done
                if printf '%s\n' "$UPGRADE_OUTPUT" | grep -qi 'error\|fatal'; then
                    log_error "brew upgrade gh failed (see log above)"
                    write_summary ERROR "gh cli" "brew upgrade failed"
                fi
            fi
            log_ok "gh CLI $(gh --version | head -1)"
            write_summary OK "gh cli" "$(gh --version | head -1)"
        else
            log "Installing gh CLI via Homebrew..."
            if ! brew install gh 2>&1 | while IFS= read -r line; do log "$line"; done; then
                log_error "brew install gh failed"
                write_summary ERROR "gh cli" "brew install failed"
            fi

            if command -v gh &>/dev/null; then
                log_ok "gh CLI installed ($(gh --version | head -1))"
                log_ok "Install path: $(command -v gh)"
                write_summary OK "gh cli" "$(gh --version | head -1)"
            else
                log_error "brew install completed but 'gh' not found in PATH"
                write_summary ERROR "gh cli" "installed but not on PATH"
            fi
        fi
        ;;

    *)
        # Linux: apt is the preferred method
        if command -v apt-get &>/dev/null; then
            if command -v gh &>/dev/null; then
                log "gh CLI already installed ($(gh --version | head -1))"
                log "Updating via apt..."
                # apt handles idempotency; keyring was added on first install
                if ! { sudo apt-get update -qq && sudo apt-get install -y gh; } 2>&1 | while IFS= read -r line; do log "$line"; done; then
                    log_error "apt-get install gh failed"
                    write_summary ERROR "gh cli" "apt-get install failed"
                fi
                if command -v gh &>/dev/null; then
                    log_ok "gh CLI updated/confirmed ($(gh --version | head -1))"
                    write_summary OK "gh cli" "$(gh --version | head -1)"
                else
                    log_error "apt-get completed but 'gh' not found in PATH"
                    write_summary ERROR "gh cli" "installed but not on PATH"
                fi
            else
                log "Installing gh CLI via apt + GitHub keyring..."
                if ! { (type -p wget >/dev/null || sudo apt-get install -y wget) \
                    && sudo mkdir -p -m 755 /etc/apt/keyrings \
                    && wget -qO- https://cli.github.com/packages/githubcli-archive-keyring.gpg | sudo tee /etc/apt/keyrings/githubcli-archive-keyring.gpg > /dev/null \
                    && sudo chmod go+r /etc/apt/keyrings/githubcli-archive-keyring.gpg \
                    && echo "deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/githubcli-archive-keyring.gpg] https://cli.github.com/packages stable main" | sudo tee /etc/apt/sources.list.d/github-cli.list > /dev/null \
                    && sudo apt-get update -qq && sudo apt-get install -y gh; } 2>&1 | while IFS= read -r line; do log "$line"; done; then
                    log_error "apt keyring + install failed for gh CLI"
                    write_summary ERROR "gh cli" "apt install failed"
                fi

                if command -v gh &>/dev/null; then
                    log_ok "gh CLI installed ($(gh --version | head -1))"
                    write_summary OK "gh cli" "$(gh --version | head -1)"
                else
                    log_error "Failed to install gh CLI via apt"
                    write_summary ERROR "gh cli" "install failed"
                fi
            fi
        else
            log_error "No supported package manager found (apt). Install gh manually: https://cli.github.com"
            write_summary ERROR "gh cli" "no supported package manager"
        fi
        ;;
esac

# --- Exit ---
if [ "$ERRORS" -gt 0 ]; then
    log "FAILED with $ERRORS error(s)" "error"
    exit 1
elif [ "$WARNINGS" -gt 0 ]; then
    log "COMPLETED with $WARNINGS warning(s)" "warn"
    exit 0
else
    log "COMPLETED successfully" "ok"
    exit 0
fi
